// Extract structured data from AI agent output and prepare for MongoDB
const items = $input.all();
const results = [];

for (const item of items) {
  // Get the AI agent's output
  const agentOutput = item.json.output || item.json.text || JSON.stringify(item.json);

  console.log('Agent output:', agentOutput);

  let structuredData = {
    job_name: 'Web Scraping Job',
    url: '',
    scraped_at: new Date().toISOString(),
    data: {},
    attributes_extracted: [],
    status: 'completed',
    user_query: item.json.chatInput || 'Unknown',
    raw_response: agentOutput.substring(0, 1000) // Limit size
  };

  try {
    // Extract URL from response
    const urlMatch = agentOutput.match(/https?:\/\/[^\s<>"\)\]]+/i);
    if (urlMatch) {
      structuredData.url = urlMatch[0];
    }

    // Try to extract JSON data from the response
    // Look for JSON in code blocks first
    let jsonMatch = agentOutput.match(/```json\s*([\s\S]*?)```/);
    if (jsonMatch) {
      structuredData.data = JSON.parse(jsonMatch[1]);
    } else {
      // Try to find raw JSON object
      jsonMatch = agentOutput.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        structuredData.data = JSON.parse(jsonMatch[0]);
      }
    }

    // Extract attributes if data was successfully parsed
    if (structuredData.data && typeof structuredData.data === 'object') {
      if (Array.isArray(structuredData.data)) {
        structuredData.attributes_extracted = Object.keys(structuredData.data[0] || {});
      } else {
        structuredData.attributes_extracted = Object.keys(structuredData.data);
      }
    }

    // Try to extract job name from conversation
    const jobMatch = agentOutput.match(/job[\s\w]*name[:\s]+["']?([^"'\n.,!?]+)/i);
    if (jobMatch) {
      structuredData.job_name = jobMatch[1].trim();
    }

  } catch (error) {
    console.log('Parse error:', error.message);
    structuredData.status = 'partial';
    structuredData.error = error.message;
    // Store the raw text if parsing failed
    structuredData.data = { 
      raw_text: agentOutput.substring(0, 500),
      note: 'Failed to parse as JSON'
    };
  }

  results.push({ json: structuredData });
}

return results;
